  "chapter_title": "হৃদয়মাজারে ভবা পাগলা: সুরের বাঁশিতে দর্শনের আলো",
  "book_name": "ভবা পাগলা",
  "book_long_title": "বাংলার আধ্যাত্মিক সাধক ও লোককবি ভবা পাগলা: জীবন ও দর্শন",
  "chapter_summary": "ভবানন্দ এখন ভবা পাগলা। তার গান ছড়িয়ে পড়েছে বাংলার আনাচে-কানাচে। এই অধ্যায়ে আমরা ভবা পাগলার গানের গভীর দর্শন এবং তার সামাজিক প্রভাবের উপর আলোকপাত করব। তাঁর গানের ভাষা ছিল অত্যন্ত সহজ, কিন্তু তার অন্তর্নিহিত অর্থ ছিল গভীর দার্শনিকতায় পূর্ণ। তিনি বুঝতেন, ঈশ্বরকে খুঁজতে হলে দূরে যেতে হয় না, তিনি আছেন মানুষের অন্তরে, প্রকৃতির মাঝে। তাঁর গান কীভাবে সামাজিক কুসংস্কার ও অন্যায়ের বিরুদ্ধে এক শক্তিশালী প্রতিবাদের প্রতীক হয়ে উঠেছিল এবং মানুষের আধ্যাত্মিক মুক্তিতে প্রভাব ফেলেছিল, তা এই অংশে বর্ণিত হয়েছে।",
  "chapter_segments": [
    {
      "segment_index": 1,
      "name": "setting_the_scene",
      "segment_title": "আশ্বিনের সন্ধ্যা ও ভবা পাগলার আঙিনা",
      "segment_seed": "হেমন্তের শিশিরভেজা ঘাস আর পদ্মাপারের নিস্তব্ধতা। একটি খড়ের ছাউনি দেওয়া আঙিনায় একতারা হাতে বসে আছেন ভবানন্দ। চারপাশে ভক্ত ও গ্রামের সাধারণ মানুষের ভিড়। ধূপের গন্ধে আর বাঁশির সুরে এক মায়াবী আধ্যাত্মিক পরিবেশের সৃষ্টি হয়েছে।"
    },
    {
      "segment_index": 2,
      "name": "character_debut",
      "segment_title": "ভবা পাগলার নবজন্ম",
      "segment_seed": "সাধারণ যুবক ভবানন্দ এখন সর্বজনবিদিত ভবা পাগলা। এলোমেলো চুল, কপালে তিলক, অঙ্গে সামান্য বসন কিন্তু চোখে এক অপার্থিব উজ্জ্বলতা। তাঁর উপস্থিতিতেই এক শান্তিময় গাম্ভীর্য নেমে আসে, যা তাঁকে সাধারণের ভিড়েও অনন্য করে তোলে।"
